def calculate_atom_economy(reaction):
    reactant_mass = 0
    product_mass = 0

    for item in reaction:
        if item == "->":
            continue
        elif reaction.index(item) < reaction.index("->"):
            reactant_mass += item[1]
        else:
            product_mass += item[1]

    atom_economy = (product_mass / reactant_mass) * 100
    return atom_economy

