            'average_duration': 0,
            'longest_outage': 0,
            'shortest_outage': 0
        }

    total_outages = len(outages)
    durations = [(end - start).total_seconds() // 60 for start, end in outages]
    average_duration = sum(durations) / total_outages
    longest_outage = max(durations)
    shortest_outage = min(durations)

    return {
        'total_outages': total_outages,
        'average_duration': average_duration,
        'longest_outage': longest_outage,
        'shortest_outage': shortest_outage
    }

