def find_most_common_element(entries):
    # Create a dictionary to store the count of each element
    element_count = {}

    # Iterate through each entry
    for entry in entries:
        # Convert the entry to lowercase for case-insensitive comparison
        entry_lower = entry.lower()

        # Split the entry into words
        words = entry_lower.split()

        # Check for occurrences of each element in the entry
        for element in ["pyramids", "pharaohs", "nile", "sphinx"]:
            if element in words:
                element_count[element] = element_count.get(element, 0) + 1

    # Find the most common element
    most_common_element = max(element_count.items(), key=lambda x: x[1], default=None)

    # If there are no occurrences, return None
    if most_common_element is None:
        return None

    # Return the most common element
    return most_common_element[0]

