def estimate_completion_date(current_progress, planned_duration, start_date):
    from datetime import datetime, timedelta

    start_date = datetime.strptime(start_date, '%Y-%m-%d')
    remaining_duration = (1 - current_progress) * planned_duration
    completion_date = start_date + timedelta(days=int(remaining_duration))

