Below is a software design in Python that adheres to the SOLID principles and incorporates the Factory Design Pattern. It manages a library of books with classes for books, authors, and publishers, and supports operations like adding new books, searching by author or title, and listing books by a specific publisher.

```python
from abc import ABC, abstractmethod
from typing import List, Dict

# Single Responsibility Principle: Each class has a single responsibility.

class Book:
    def __init__(self, title: str, author: str, publisher: str):
        self.title = title
        self.author = author
        self.publisher = publisher

class Author:
    def __init__(self, name: str):
        self.name = name

class Publisher:
    def __init__(self, name: str):
        self.name = name

# Open/Closed Principle: The system is open for extension but closed for modification.

class BookRepository(ABC):
    @abstractmethod
    def add_book(self, book: Book):
        pass

    @abstractmethod
    def find_books_by_author(self, author: str) -> List[Book]:
        pass

    @abstractmethod
    def find_books_by_title(self, title: str) -> List[Book]:
        pass

    @abstractmethod
    def list_books_by_publisher(self, publisher: str) -> List[Book]:
        pass

class InMemoryBookRepository(BookRepository):
    def __init__(self):
        self.books: List[Book] = []

    def add_book(self, book: Book):
        self.books.append(book)

    def find_books_by_author(self, author: str) -> List[Book]:
        return [book for book in self.books if book.author == author]

    def find_books_by_title(self, title: str) -> List[Book]:
        return [book for book in self.books if book.title == title]

    def list_books_by_publisher(self, publisher: str) -> List[Book]:
        return [book for book in self.books if book.publisher == publisher]

# Liskov Substitution Principle: Derived classes should be substitutable for base classes.
# BookRepository subclasses can substitute for the base class.

# Interface Segregation Principle: Interfaces are split to ensure implementing classes are not forced to implement unused methods.
# BookRepository is a fine example of a focused interface.

# Dependency Inversion Principle: High-level modules should not depend on low-level modules. Both should depend on abstractions.

class Library:
    def __init__(self, book_repository: BookRepository):
        self.book_repository = book_repository

    def add_book(self, title: str, author: str, publisher: str):
        book = Book(title, author, publisher)
        self.book_repository.add_book(book)

    def search_books_by_author(self, author: str) -> List[Book]:
        return self.book_repository.find_books_by_author(author)

    def search_books_by_title(self, title: str) -> List[Book]:
        return self.book_repository.find_books_by_title(title)

    def list_books_by_publisher(self, publisher: str) -> List[Book]:
        return self.book_repository.list_books_by_publisher(publisher)

# Factory Design Pattern: Creates objects without specifying the exact class of the object that will be created.

class BookRepositoryFactory:
    @staticmethod
    def create_repository(repository_type: str) -> BookRepository:
        if repository_type == "in-memory":
            return InMemoryBookRepository()
        else:
            raise ValueError("Unknown repository type")

# Setting up the library system using the factory and repository pattern

repository = BookRepositoryFactory.create_repository("in-memory")
library = Library(repository)

# Example Usage
library.add_book("The Great Gatsby", "F. Scott Fitzgerald", "Scribner")
library.add_book("1984", "George Orwell", "Secker & Warburg")
library.add_book("Animal Farm", "George Orwell", "Secker & Warburg")

# Searching for books
