def calculate_average_age_for_condition(patient_records, condition):
    total_age = 0
    count = 0

    for record in patient_records:
        if condition in record['conditions']:
            total_age += record['age']
            count += 1

    if count == 0:
        return 0.0
    else:
        return total_age / count

def categorize_recordings(recordings):
    low_range = range(20, 251)
    medium_range = range(251, 2001)
    high_range = range(2001, 20001)

    low_recordings = []
    medium_recordings = []
    high_recordings = []

    for recording in recordings:
        low_count = sum(freq in low_range for freq in recording)
        medium_count = sum(freq in medium_range for freq in recording)
        high_count = sum(freq in high_range for freq in recording)

        total_count = len(recording)

        if low_count >= total_count * 0.5:
            low_recordings.append(recording)
        elif medium_count >= total_count * 0.5:
            medium_recordings.append(recording)
        elif high_count >= total_count * 0.5:
            high_recordings.append(recording)

    return {
        "Low": low_recordings,
        "Medium": medium_recordings,
        "High": high_recordings
    }

