def analyze_reaction_times(reaction_times):
    if not reaction_times:
        return None

    reaction_times.sort()
    q1 = reaction_times[len(reaction_times) // 4]
    q3 = reaction_times[3 * len(reaction_times) // 4]
    iqr = q3 - q1
    lower_bound = q1 - 1.5 * iqr
    upper_bound = q3 + 1.5 * iqr

    filtered_times = [time for time in reaction_times if lower_bound <= time <= upper_bound]

    if not filtered_times:
        return None

    return sum(filtered_times) / len(filtered_times)

