def is_universal_number(n):
    # Convert the number to a string to handle reversing digits
    n_str = str(abs(n))

    # Check if the number is a palindrome
    if n_str != n_str[::-1]:
        return False

    # Calculate the sum of digits
    digit_sum = sum(int(digit) for digit in n_str)

    # Check if the number is divisible by the sum of its digits
    if n % digit_sum == 0:
        return True
    else:
        return False

